class Solution {
public:
    bool areSentencesSimilar(string s1, string s2) {
        if (s1.size() < s2.size()) swap(s1, s2);
        int n = s1.size(), m = s2.size();
        int k = 1;
        for (char c : s2) if (c == ' ') k++;

        int i = 0, j = 0, pre = 0;
        while (j < m) {
            int ii = i, jj = j;
            while (jj < m && s2[jj] != ' ' && ii < n && s1[ii] == s2[jj]) {
                ii++; jj++;
            }
            bool s2End = (jj == m || s2[jj] == ' ');
            bool s1End = (ii == n || s1[ii] == ' ');
            if (s2End && s1End) {
                pre++;
                while (jj < m && s2[jj] == ' ') jj++;
                while (ii < n && s1[ii] == ' ') ii++;
                i = ii; j = jj;
            } else {
                break;
            }
        }

        int a = n - 1, b = m - 1, suf = 0;
        while (b >= 0) {
            int aa = a, bb = b;
            while (bb >= 0 && s2[bb] != ' ' && aa >= 0 && s1[aa] == s2[bb]) {
                aa--; bb--;
            }
            bool s2End = (bb < 0 || s2[bb] == ' ');
            bool s1End = (aa < 0 || s1[aa] == ' ');
            if (s2End && s1End) {
                suf++;
                while (bb >= 0 && s2[bb] == ' ') bb--;
                while (aa >= 0 && s1[aa] == ' ') aa--;
                a = aa; b = bb;
            } else {
                break;
            }
        }

        return pre + suf >= k;
    }
};
